      connectionName: CONNECTION_NAME,
      pageSize: 100,
      ...(pageToken ? { pageToken } : {}),
    })) as ListConnectedAccountsResponseLike;

    if (
      response.connectedAccounts?.some((account) => account.identifier === identifier)
    ) {
      return true;
    }

    pageToken = response.nextPageToken || undefined;
  } while (pageToken);

  return false;
}

